def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != 1}

    # The two fragments, including their gray alignment marks, are separate
    # connected components.
    parts = []
    while cells:
        stack = [cells.pop()]
        part = set(stack)
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        part.add(p)
                        stack.append(p)
        parts.append(part)

    if len(parts) != 2:
        return [[1 if x == 7 else x for x in row] for row in grid]

    def solve(a, b):
        ay = {(r, c) for r, c in a if grid[r][c] == 4}
        by = {(r, c) for r, c in b if grid[r][c] == 4}
        ag = {(r, c) for r, c in a if grid[r][c] == 7}
        bg = {(r, c) for r, c in b if grid[r][c] == 7}
        if not ag or not bg:
            return None

        # Each gray mark denotes cells supplied by the other fragment.
        # Try the translations implied by matching a mark to a yellow cell.
        for gr, gc in ag:
            for br, bc in by:
                dr, dc = gr - br, gc - bc
                moved_b = {(r + dr, c + dc) for r, c in by}
                if not all((r, c) in moved_b for r, c in ag):
                    continue
                if not all((r + dr, c + dc) in ay for r, c in bg):
                    continue
                yellow = ay | moved_b
                if not yellow:
                    return None
                r0 = min(r for r, c in yellow)
                r1 = max(r for r, c in yellow)
                c0 = min(c for r, c in yellow)
                c1 = max(c for r, c in yellow)
                return [[4 if (r, c) in yellow else 1
                         for c in range(c0, c1 + 1)]
                        for r in range(r0, r1 + 1)]
        return None

    ans = solve(parts[0], parts[1])
    if ans is None:
        ans = solve(parts[1], parts[0])
    if ans is not None:
        return ans
    return [[1 if x == 7 else x for x in row] for row in grid]
